--region logic

---FreshUI
---@param goodsInfo table {
---     vo: CardFavorableGoodsVo | RestaurantCookingGoodsVo
---     ownNum : number
---     isFavor: boolean
---     favorAddiNum: number
---}
---@param index number
function CardProgressionFavorPopupCell:FreshUI(goodsInfo, index, isSelect)
    ---@type CardFavorableGoodsVo | RestaurantCookingGoodsVo
    local vo = goodsInfo.vo
    local ownNum = goodsInfo.ownNum

    local env = CfUtils.GetLuaScr(self.GoodNode, GoodsNodePath)
    if isNotNull(env) then
        local goodsId = vo.id
        env:Reload(
                {
                    goodsId = goodsId,
                    text = ownNum,
                    isShowNo = true
                }
        )
        env:SetClickCallback(function()
            if ownNum <= 0 then
                GameUtils.ShowCommonGoodsTipsBoard(self.GoodNode, goodsId, true)
                return
            end
            if self._callback then
                self._callback(index)
            end
        end)
        env:SetCheckState(isSelect)
    end
    -- KTool.SetActive(self.NotEnough.gameObject, ownNum == 0)
    KTool.SetActive(self.ImgFavorite.gameObject, goodsInfo.isFavor)
end

function CardProgressionFavorPopupCell:FreshSelectState(isSelect)
    ---@type GoodNodeMB
    local env = CfUtils.GetLuaScr(self.GoodNode, GoodsNodePath)
    if isNotNull(env) then
        env:SetCheckState(isSelect)
    end
end

--endregion


--region get/set

function CardProgressionFavorPopupCell:SetCallback(callback)
    self._callback = callback
end

